"""EIP-7702 round-trip delegate — compiled artifact + calldata helpers.

RoundTrip7702.sol compiled with solc 0.8.20 (--optimize --optimize-runs 200),
the same compiler the reference delegate used. The trading EOA sets a 7702
delegation to a deployed instance of this bytecode, then calls roundTrip(...) on
itself to do an atomic IOC buy + IOC sell in one transaction. See
backend/contracts/RoundTrip7702.sol for the source and rationale.

To regenerate after editing the .sol:
  docker run --rm -v "$PWD/contracts":/src ethereum/solc:0.8.20 \
    --optimize --optimize-runs 200 --bin --abi --combined-json bin,abi \
    /src/RoundTrip7702.sol
and paste the RoundTrip7702 `bin` into ROUNDTRIP_INITCODE below.
"""
from web3 import Web3

# Creation bytecode (initcode): deploys the runtime and returns it.
ROUNDTRIP_INITCODE = (
    ""
)

ROUNDTRIP_ABI = [{
    "inputs": [
        {"name": "base", "type": "address"}, {"name": "quote", "type": "address"},
        {"name": "pool", "type": "address"}, {"name": "buyPrice", "type": "uint256"},
        {"name": "sellPrice", "type": "uint256"}, {"name": "qty", "type": "uint256"},
        {"name": "expireNs", "type": "uint64"}, {"name": "maxTollQuote", "type": "uint256"},
        {"name": "lot", "type": "uint256"},
    ],
    "name": "roundTrip", "outputs": [], "stateMutability": "nonpayable", "type": "function",
}, {
    "anonymous": False, "name": "Trip", "type": "event",
    "inputs": [
        {"indexed": False, "name": "spentQuote", "type": "uint256"},
        {"indexed": False, "name": "gotBase", "type": "uint256"},
        {"indexed": False, "name": "soldBase", "type": "uint256"},
    ],
}]

ROUNDTRIP_SELECTOR = "0x0d8bb330"
# keccak256("Trip(uint256,uint256,uint256)")
TRIP_TOPIC = "0x3fd41717476fe5a7a3d5e8b93c926baefc236e347f26f78fb8e3865af87b437a"

_w3 = Web3()
_contract = _w3.eth.contract(abi=ROUNDTRIP_ABI)


def encode_roundtrip(base, quote, pool, buy_price, sell_price, qty,
                     expire_ns, max_toll_quote, lot) -> str:
    """ABI-encode a roundTrip(...) call. All numeric args are raw integers
    (already scaled by decimals / snapped by the caller)."""
    return _contract.encode_abi("roundTrip", args=[
        Web3.to_checksum_address(base), Web3.to_checksum_address(quote),
        Web3.to_checksum_address(pool), int(buy_price), int(sell_price),
        int(qty), int(expire_ns), int(max_toll_quote), int(lot),
    ])


def decode_trip(receipt) -> dict | None:
    """Pull the Trip event out of a tx receipt. Returns raw integer amounts
    {spent_quote, got_base, sold_base}, or None if the trip emitted no Trip
    (e.g. it reverted). The event has 3 non-indexed uint256 words in the data."""
    for lg in receipt.get("logs", []):
        topics = lg.get("topics", [])
        t0 = topics[0].hex() if topics and hasattr(topics[0], "hex") else (topics[0] if topics else "")
        if isinstance(t0, str) and not t0.startswith("0x"):
            t0 = "0x" + t0
        if t0.lower() == TRIP_TOPIC:
            data = lg["data"]
            data = data.hex() if hasattr(data, "hex") else data
            data = data[2:] if data.startswith("0x") else data
            return {
                "spent_quote": int(data[0:64], 16),
                "got_base":    int(data[64:128], 16),
                "sold_base":   int(data[128:192], 16),
            }
    return None
